class Solution {
public:
    string decodeString(string s) {
        stack<int> counts;
        stack<string> texts;
        string cur;
        int num = 0;
        for (int i = 0; i < (int)s.size(); i++) {
            char c = s[i];
            if (isdigit(c)) {
                num = num * 10 + (c - '0');
            } else if (c == '[') {
                counts.push(num);
                texts.push(cur);
                num = 0;
                cur = "";
            } else if (c == ']') {
                string inner = cur;
                cur = texts.top();
                texts.pop();
                for (int k = counts.top(); k > 0; k--) cur += inner;
                counts.pop();
            } else {
                cur.push_back(c);
            }
        }
        return cur;
    }
};
